package org.securemail.community.agent;
import org.junit.jupiter.api.Test;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Independent central parser/fetch seam tests; no production news service is contacted. */
final class CentralEvidenceVerifierTest {
 record Fixture(Map<String,Object>policy,List<Map<String,Object>>observations,Map<String,Object>draft,Map<String,byte[]>wire){}
 Fixture fixture()throws Exception{List<Map<String,Object>>sources=new ArrayList<>(),observations=new ArrayList<>();Map<String,byte[]>wire=new HashMap<>();List<String>urls=new ArrayList<>();for(int n=0;n<2;n++){String id=UUID.randomUUID().toString(),url="https://source"+n+".example/rss",article="https://source"+n+".example/article";var source=Map.<String,Object>of("id",id,"url",url,"independenceGroup","owner"+n,"official",true,"minIntervalMinutes",15,"cityId","ru/ru-mow/moscow");sources.add(source);String xml="<rss><channel><item><title>Новость</title><description>Независимое описание события источником "+n+".</description><link>"+article+"</link><pubDate>Thu, 15 Oct 2026 12:00:00 GMT</pubDate></item></channel></rss>";byte[]bytes=xml.getBytes(StandardCharsets.UTF_8);wire.put(url,bytes);var observation=new LinkedHashMap<>(new SourceParser().parse(id,"owner"+n,true,"ru/ru-mow/moscow",URI.create(url),"application/rss+xml",bytes).get(0).map());observation.put("publicSource",true);observations.add(observation);urls.add(article);}return new Fixture(Map.of("sources",sources),observations,Map.of("sources",urls),wire);}
 PublicSourceHttp transport(Fixture f){return new PublicSourceHttp(host->new InetAddress[]{InetAddress.getByName("8.8.8.8")},(uri,ip,max)->{if(uri.getPath().equals("/robots.txt"))return new PublicSourceHttp.Response(404,Map.of(),new byte[0],uri);byte[]data=f.wire.get(uri.toString());return new PublicSourceHttp.Response(data==null?404:200,Map.of("content-type","application/rss+xml"),data==null?new byte[0]:data,uri);});}
 @Test void independentlyFetchedMatchingEvidenceCanPassAndHasReceipts()throws Exception{Fixture f=fixture();try(var verifier=new CentralEvidenceVerifier(transport(f))){var proof=verifier.verify(f.policy,f.observations,f.draft);assertTrue(proof.verified());assertEquals(2,proof.receipts().size());assertTrue(proof.receipts().stream().allMatch(r->r.get("sha256").toString().matches("[a-f0-9]{64}")));}}
 @Test void workerCannotSelfApproveFabricatedArticleTextUrlOrGroup()throws Exception{for(String field:List.of("text","url","sourceGroup")){Fixture f=fixture();f.observations.get(0).put(field,field.equals("url")?"https://other.example/forged":"Вымышленное подтверждение");try(var verifier=new CentralEvidenceVerifier(transport(f))){assertFalse(verifier.verify(f.policy,f.observations,f.draft).verified(),field);}}}
 @Test void centralSourceChangesOrUnavailabilityForceEditorialReview()throws Exception{Fixture f=fixture();String first=f.wire.keySet().iterator().next();f.wire.put(first,"<rss><channel/></rss>".getBytes(StandardCharsets.UTF_8));try(var verifier=new CentralEvidenceVerifier(transport(f))){assertFalse(verifier.verify(f.policy,f.observations,f.draft).verified());}}
 @Test void identicalSyndicatedTextIsNotIndependentConfirmation()throws Exception{Fixture f=fixture();for(var e:f.wire.entrySet()){String xml=new String(e.getValue(),StandardCharsets.UTF_8).replaceAll("источником [01]", "одним первичным источником");e.setValue(xml.getBytes(StandardCharsets.UTF_8));}for(var o:f.observations)o.put("text","Независимое описание события одним первичным источником.");try(var verifier=new CentralEvidenceVerifier(transport(f))){var proof=verifier.verify(f.policy,f.observations,f.draft);assertFalse(proof.verified());assertEquals("SYNDICATED_OR_SINGLE_SOURCE",proof.reason());}}
 @Test void mixedPrivateDnsCannotBeUsedForCentralSourceProof()throws Exception{Fixture f=fixture();var http=new PublicSourceHttp(h->new InetAddress[]{InetAddress.getByName("169.254.169.254")},(u,ip,m)->{throw new AssertionError("Must not connect to metadata service");});try(var verifier=new CentralEvidenceVerifier(http)){assertFalse(verifier.verify(f.policy,f.observations,f.draft).verified());}}
}
